// Placeholder: pass through sheet row. Replace this node with an OpenAI (or AI) node that
// generates title, slug, body, excerpt, featured_image_url, featured_image_alt, meta_title, meta_description.
// Output should be one item per row with those fields (or merge with sheet row).
const items = $input.all();
return items.map(item => {
  const j = item.json;
  return {
    json: {
      title: j.title || j.topic || 'Untitled',
      slug: j.slug || (j.topic || '').toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, ''),
      body_html: j.body_html || j.content || '',
      excerpt: j.excerpt || '',
      featured_image_url: j.featured_image_url || '',
      featured_image_alt: j.featured_image_alt || '',
      meta_title: j.meta_title || j.title || j.topic,
      meta_description: j.meta_description || j.excerpt || '',
      status: j.status || 'draft',
      published_at: j.published_at || null
    }
  };
});
